package com.hrtbuddy;
import android.app.*; import android.content.*; import android.os.Build; import android.graphics.drawable.Icon; import java.time.*; import java.util.*;
public class ReminderReceiver extends BroadcastReceiver {
 public void onReceive(Context c,Intent i){ String action=i.getAction(); if("done".equals(action)||"skip".equals(action)){String key=i.getStringExtra("key"); State.finish(c,key,"skip".equals(action)); ((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(notificationId(key)); schedule(c); return;} String key=i.getStringExtra("key"); if(key==null){ notify(c,"pill"); notify(c,"patch"); notify(c,"checkin"); } else notify(c,key); schedule(c); }
 static boolean isPatchDay(Context c){String days=State.p(c).getString("patchDays","TUE,SAT");String n=State.careDate().getDayOfWeek().toString().substring(0,3);return days.contains(n);}
 static void testNotify(Context c,String key){ show(c,key); }
 static void notify(Context c,String key){ if(State.confirmed(c,key)||!State.scheduled(c,State.careDate(),key))return; show(c,key); }
 static int notificationId(String key){return key.equals("pill")?20:key.equals("patch")?21:22;}
 static void show(Context c,String key){ String title=key.equals("pill")?"Progesterone reminder":key.equals("patch")?"Patch change reminder":"Health check"; String text=key.equals("pill")?"Take your progesterone tablet":key.equals("patch")?"Change your HRT patch":"Open to record today’s health check"; PendingIntent content=key.equals("checkin")?openHealth(c):PendingIntent.getActivity(c,key.equals("pill")?10:11,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE); PendingIntent done=key.equals("checkin")?openHealth(c):action(c,key,"done",key.equals("pill")?14:15); PendingIntent skip=action(c,key,"skip",key.equals("pill")?17:key.equals("patch")?18:19); Icon icon=Icon.createWithResource(c,com.hrtbuddy.R.drawable.ic_notification); Notification n=new Notification.Builder(c,"hrt_v2").setSmallIcon(com.hrtbuddy.R.drawable.ic_notification).setContentTitle(title).setContentText(text).setContentIntent(content).addAction(new Notification.Action.Builder(icon,key.equals("checkin")?"Complete":"Done",done).build()).addAction(new Notification.Action.Builder(icon,"Skip",skip).build()).setOngoing(true).setAutoCancel(false).setPriority(Notification.PRIORITY_MAX).setVisibility(Notification.VISIBILITY_PUBLIC).setCategory(Notification.CATEGORY_REMINDER).build(); ((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(notificationId(key),n); }
 static PendingIntent openHealth(Context c){ Intent i=new Intent(c,MainActivity.class).putExtra("open_health_check",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP); return PendingIntent.getActivity(c,12,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE); }
 static PendingIntent action(Context c,String key,String action,int request){ Intent i=new Intent(c,ReminderReceiver.class).setAction(action).putExtra("key",key); return PendingIntent.getBroadcast(c,request,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE); }
 static void schedule(Context c){ scheduleOne(c,"patch",State.p(c).getString("patchTime","10:00"),1); scheduleOne(c,"pill",State.p(c).getString("progTime","22:00"),2); scheduleOne(c,"checkin",State.p(c).getString("checkinTime","20:00"),3); }
 static void scheduleOne(Context c,String key,String time,int request){ AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE); Intent i=new Intent(c,ReminderReceiver.class).putExtra("key",key); PendingIntent pi=PendingIntent.getBroadcast(c,request,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE); Calendar cal=Calendar.getInstance(); String[] t=time.split(":"); cal.set(Calendar.HOUR_OF_DAY,Integer.parseInt(t[0])); cal.set(Calendar.MINUTE,Integer.parseInt(t.length>1?t[1]:"0")); cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0); if(cal.getTimeInMillis()<=System.currentTimeMillis())cal.add(Calendar.DATE,1); if(Build.VERSION.SDK_INT>=31&&am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,cal.getTimeInMillis(),pi); else if(Build.VERSION.SDK_INT>=23)am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,cal.getTimeInMillis(),pi); else am.set(AlarmManager.RTC_WAKEUP,cal.getTimeInMillis(),pi); }
}
